            self.enaIcoTun = self['tuner'].instance.size().width() != 0
        except:
            pass
        if config.plugins.setupGlass17.par58.value and ECL or self.enaWeainf:
            if self.enaWeainf:
                self.refreshWeatherNow()
            else:
                self.clrMemTimer.startLongTimer(30)
        self.cpu_count = 0
